"""统一的网络策略：超时、重试分级、错误可见（issue #30）。

背景
----
pdf2zh 原本有三个叠加的问题，合起来让「API 报错」表现成「翻译极慢 / 卡住不动」：

1. ``converter.py`` 里翻译 worker 的重试装饰器是 ``@retry(wait=wait_fixed(1))``，
   没有给 ``stop=``。tenacity 默认 ``stop_never`` —— 永不放弃。API Key 失效返回
   401 这种**永久性错误**，重试一万次也不可能成功，于是任务永远不结束。
   实测：key 失效时 60 秒内重试 34 次，进度条一动不动。

2. ``openai.OpenAI(...)`` 没设 ``timeout``/``max_retries``，吃 SDK 默认值
   （读超时 600 秒、自动重试 2 次）→ **单个段落一次调用最坏 1800 秒 = 30 分钟**。
   一页要等它所有段落都完成，一个段落卡住整页就卡住。

3. ``translator.py`` 里 6 处 ``requests`` 调用全都没有 ``timeout=``，
   连接挂住就一直挂着。

整类根治
--------
不逐个去改几十个调用点（改漏一处就白改），而是在**入口处**统一装上策略：

* ``openai.OpenAI`` / ``openai.AzureOpenAI`` 构造时注入默认超时与重试上限
* ``requests.Session.request`` 注入默认超时
* ``BaseTranslator.translate`` 包一层：区分永久性错误与暂时性错误

永久性错误（401/402/403/404 等）→ 立刻停止整个任务并把原因报给用户，不再重试。
暂时性错误（超时、连接失败、429、5xx）→ 有限次退避重试，仍失败则记为警告、
该段落保留原文，不拖垮整篇。

用法::

    from pdf2zh.net_policy import install, get_state
    state = install(cancellation_event=ev)
    ...                       # 跑翻译
    if state.aborted:
        raise RuntimeError(state.abort_reason)
"""

from __future__ import annotations

import logging
import threading
import time

logger = logging.getLogger(__name__)

# 这些 HTTP 状态码重试再多次也不会变成功，必须立刻停并告诉用户
PERMANENT_STATUS = {400, 401, 402, 403, 404, 405, 422}

# 这些是暂时性的，值得退避重试
TRANSIENT_STATUS = {408, 409, 425, 429, 500, 502, 503, 504, 529}

DEFAULT_TIMEOUT = 60.0      # 单次请求读超时（秒）。原本是 SDK 默认的 600 秒
DEFAULT_MAX_ATTEMPTS = 3    # 暂时性错误的最大尝试次数（含首次）
DEFAULT_SDK_RETRIES = 0     # 交给我们自己重试，不让 SDK 再叠一层

# 免费的「网页抓取」类翻译服务：没有 key，是蹭谷歌/必应的公开网页接口，谷歌按
# **出口 IP** 限流。这类服务的 429 跟本地线程数无关（实测单线程、每 10 秒 1 次
# 照样 429），换节点/重试通常也没用——所以给用户的说明必须和付费 API 的 429 分开：
# 付费 API 的 429 才是「你自己发太快」，值得调小线程数。
_FREE_SCRAPE_SERVICES = {"google", "bing"}


def _svc_label(name: str) -> str:
    return {"google": "Google 翻译", "bing": "Bing 翻译"}.get(name, "免费网页翻译")

_FRIENDLY = {
    400: "请求格式被服务端拒绝（400）。可能是模型名填错，或该服务不支持当前参数。",
    401: "API Key 无效或已过期（401）。请到「设置」里检查该服务的 Key。",
    402: "账户余额不足（402）。请先充值，或换一个翻译服务。",
    403: "没有访问权限（403）。可能是 Key 权限不足、该模型未开通，或所在地区受限。",
    404: "接口地址或模型不存在（404）。请检查「设置」里的接口地址（Base URL）和模型名。",
    405: "接口不支持该请求方式（405）。请检查接口地址是否填成了网页地址。",
    422: "请求参数不合法（422）。请检查模型名与接口地址是否匹配。",
}


class _State:
    """记录本次翻译过程中发生的网络错误，供界面读取。"""

    def __init__(self):
        self.lock = threading.Lock()
        self.aborted = False
        self.abort_reason = ""      # 面向用户的中文说明
        self.abort_detail = ""      # 原始异常文本，写日志用
        self.warnings = []          # [(段落前若干字, 原因)] 暂时性失败，已保留原文
        self.ok_count = 0           # 成功翻译的段落数
        self.fail_count = 0         # 保留原文的段落数（不受 warnings 50 上限影响）
        self.service = ""           # 当前翻译服务标识（google/bing/deepseek…），用于分场景措辞
        self.cancellation_event = None

    def abort(self, reason: str, detail: str = ""):
        with self.lock:
            if self.aborted:
                return
            self.aborted = True
            self.abort_reason = reason
            self.abort_detail = detail
        logger.error("翻译中止：%s | %s", reason, detail[:300])
        # 让 pdf2zh 主循环在下一个页面边界退出，而不是继续产出一份没翻译的 PDF
        ev = self.cancellation_event
        if ev is not None:
            try:
                ev.set()
            except Exception:
                pass

    def ok(self):
        with self.lock:
            self.ok_count += 1

    def warn(self, sample: str, reason: str):
        with self.lock:
            self.fail_count += 1
            if len(self.warnings) < 50:
                self.warnings.append((sample[:40], reason))

    @property
    def failed_count(self) -> int:
        with self.lock:
            return self.fail_count

    @property
    def mostly_failed(self) -> bool:
        """大面积段落都保留了原文 —— 基本可以断定是网络/服务不通，
        产物是一份没翻译的 PDF，绝不能当成功交付。"""
        with self.lock:
            total = self.ok_count + self.fail_count
            return total >= 5 and self.fail_count >= total * 0.6

    @property
    def failure_hint(self) -> str:
        """给用户的一句话原因（取最常见的那条失败原因）。"""
        with self.lock:
            return self.warnings[0][1] if self.warnings else "网络不稳定或翻译服务不可用"

    @property
    def network_failure_message(self) -> str:
        """大面积失败时给用户的完整说明。两端 worker 共用，别各写一遍。"""
        with self.lock:
            total = self.ok_count + self.fail_count
            fail = self.fail_count
            hint = self.warnings[0][1] if self.warnings else "网络不稳定或翻译服务不可用"
            svc = self.service or ""
        head = (f"大部分内容未能翻译（{fail}/{total} 段保留了英文原文）。\n"
                f"原因：{hint}")
        if svc in _FREE_SCRAPE_SERVICES:
            # 免费网页翻译被谷歌按 IP 限流：讲清楚「不是你的问题、调线程没用」，直接指向 DeepSeek
            tail = (f"\n\n为什么会这样：{_svc_label(svc)}是免费蹭谷歌/必应的公开网页接口，"
                    f"谷歌按“出口 IP”限流。翻墙时大家挤在同一批公共出口 IP 上，很容易被限；"
                    f"一旦被限，调线程数、重试、换节点通常都没用（这不是你电脑或软件的问题）。\n"
                    f"建议改用 DeepSeek：国内无需翻墙，按你自己的账号算额度，稳定不受影响。")
        else:
            tail = ("\n\n请检查网络后重试。若持续失败，国内建议改用 DeepSeek"
                    "（无需翻墙，按账号计额度）。")
        return head + tail


_state = _State()
_installed = False
_install_lock = threading.Lock()


def get_state() -> _State:
    return _state


def reset(cancellation_event=None, service: str = "") -> _State:
    """每次翻译任务开始前调用，清掉上一次的错误记录。"""
    global _state
    _state = _State()
    _state.cancellation_event = cancellation_event
    # service 可能是 "google" 或 "deepseek:model"，取冒号前、转小写
    _state.service = (service or "").split(":", 1)[0].strip().lower()
    return _state


def _status_of(exc) -> int | None:
    """从各种异常里把 HTTP 状态码抠出来。"""
    for attr in ("status_code", "code", "http_status"):
        v = getattr(exc, attr, None)
        if isinstance(v, int) and 100 <= v < 600:
            return v
    resp = getattr(exc, "response", None)
    if resp is not None:
        v = getattr(resp, "status_code", None)
        if isinstance(v, int):
            return v
    return None


def classify(exc) -> tuple[str, str]:
    """把异常分成 permanent / transient，并给出面向用户的说明。"""
    status = _status_of(exc)
    if status in PERMANENT_STATUS:
        return "permanent", _FRIENDLY.get(status, f"服务端拒绝了请求（HTTP {status}）。")
    if status in TRANSIENT_STATUS:
        if status == 429:
            svc = getattr(_state, "service", "") or ""
            if svc in _FREE_SCRAPE_SERVICES:
                # 免费网页翻译的 429 是出口 IP 被限，跟线程数无关，别再让用户白调
                return "transient", f"{_svc_label(svc)}被限流（429，与线程数无关）"
            return "transient", "请求过于频繁被限流（429）。可以把「线程数」调小一些。"
        return "transient", f"服务端暂时故障（HTTP {status}）。"

    name = type(exc).__name__
    text = str(exc)
    # 没有状态码的情况：按异常类型判断
    if "Authentication" in name or "authentication" in text.lower():
        return "permanent", _FRIENDLY[401]
    if "PermissionDenied" in name:
        return "permanent", _FRIENDLY[403]
    if "NotFound" in name:
        return "permanent", _FRIENDLY[404]
    if "Timeout" in name or "timed out" in text.lower():
        return "transient", "请求超时。可能是网络不稳定，或该服务当前响应很慢。"
    if "Connection" in name or "ProxyError" in name:
        return "transient", "连不上翻译服务。请检查网络或代理设置。"
    if status is not None:
        return "transient", f"服务端返回 HTTP {status}。"
    return "transient", f"{name}: {text[:150]}"


# ── 具体的补丁 ────────────────────────────────────────────────────────────

def _patch_openai(timeout: float, sdk_retries: int):
    try:
        import openai
    except ImportError:
        return 0
    n = 0
    for cls_name in ("OpenAI", "AzureOpenAI"):
        cls = getattr(openai, cls_name, None)
        if cls is None or getattr(cls, "_pdf2zh_patched", False):
            continue
        orig = cls.__init__

        def make(orig_init):
            def __init__(self, *a, **kw):
                # 调用方没显式指定就用我们的默认值；显式指定的一律尊重
                kw.setdefault("timeout", timeout)
                kw.setdefault("max_retries", sdk_retries)
                return orig_init(self, *a, **kw)
            return __init__

        cls.__init__ = make(orig)
        cls._pdf2zh_patched = True
        n += 1
    return n


def _patch_requests(timeout: float):
    try:
        import requests
    except ImportError:
        return 0
    sess = requests.Session
    if getattr(sess, "_pdf2zh_patched", False):
        return 0
    orig = sess.request

    def request(self, method, url, **kw):
        if kw.get("timeout") is None:
            kw["timeout"] = timeout
        return orig(self, method, url, **kw)

    sess.request = request
    sess._pdf2zh_patched = True
    return 1


def _patch_translator(max_attempts: int):
    try:
        from pdf2zh.translator import BaseTranslator
    except ImportError:
        return 0
    if getattr(BaseTranslator, "_pdf2zh_policy_patched", False):
        return 0
    orig = BaseTranslator.translate

    def translate(self, text, ignore_cache=False):
        st = _state
        # 已经因为永久性错误中止了，后续段落直接原样返回，让任务尽快收尾
        if st.aborted:
            return text

        delay = 1.0
        for attempt in range(1, max_attempts + 1):
            try:
                result = orig(self, text, ignore_cache)
                st.ok()
                return result
            except BaseException as e:  # noqa: BLE001 — 要拦住所有异常做分级
                kind, reason = classify(e)
                if kind == "permanent":
                    # 重试不可能成功：立刻停掉整个任务，把原因报给用户
                    st.abort(reason, f"{type(e).__name__}: {e}")
                    return text
                if attempt >= max_attempts:
                    # 暂时性错误重试完了还不行：这一段保留原文，不拖垮整篇
                    st.warn(text, reason)
                    logger.warning("段落翻译失败（已重试 %d 次），保留原文：%s",
                                   max_attempts, reason)
                    return text
                if st.aborted:
                    return text
                time.sleep(delay)
                delay = min(delay * 2, 8.0)   # 指数退避，封顶 8 秒
        return text

    BaseTranslator.translate = translate
    BaseTranslator._pdf2zh_policy_patched = True
    return 1


def install(timeout: float = DEFAULT_TIMEOUT,
            max_attempts: int = DEFAULT_MAX_ATTEMPTS,
            sdk_retries: int = DEFAULT_SDK_RETRIES,
            cancellation_event=None,
            service: str = "") -> _State:
    """装上网络策略并重置错误记录。可以重复调用（补丁只装一次）。"""
    global _installed
    st = reset(cancellation_event, service)
    with _install_lock:
        if not _installed:
            a = _patch_openai(timeout, sdk_retries)
            b = _patch_requests(timeout)
            c = _patch_translator(max_attempts)
            _installed = True
            logger.info("网络策略已装载：openai 客户端 %d 个、requests %d、翻译器 %d；"
                        "超时 %.0fs、最多尝试 %d 次", a, b, c, timeout, max_attempts)
    return st


def summary() -> str:
    """任务结束后给界面用的一句话总结；没问题就返回空串。"""
    st = _state
    if st.aborted:
        return st.abort_reason
    n = st.failed_count
    if n:
        return f"有 {n} 段翻译失败已保留原文（{st.warnings[0][1]}）"
    return ""
